// slotHistoryLocked 返回该槽按保存生效次序排列的记录标识（最新在前、
// 槽首记录在末尾），以及指针当前指向的最新标识。
//
// 优先使用指针内嵌的历史索引；旧版本指针没有该索引时，在内存中沿
// “校验通过”的记录父链回退重建，绝不在此时改写目录。链上遇到缺失、
// 无法解析或校验不过的记录就停止——无法确认归属的更老记录不再使用。
// 槽首标记只取自校验通过的信封，因此受损记录里被篡改的父标识或槽首
// 标记既不能把遍历引向别的槽，也不能遮住本槽更早的可用记录。
func (a *Archive) slotHistoryLocked(slot string) (latest RecordID, history []RecordID, err error) {
	p, err := a.readSlotPointerLocked(slot)
	if err != nil {
		return "", nil, err
	}
	if len(p.History) > 0 {
		return p.Latest, p.History, nil
	}
	history, err = a.rebuildHistoryLocked(slot, p.Latest)
	if err != nil {
		return "", nil, err
	}
	return p.Latest, history, nil
}

// rebuildHistoryLocked 从 latest 起沿校验通过的父链在内存中重建历史。
func (a *Archive) rebuildHistoryLocked(slot string, latest RecordID) ([]RecordID, error) {
	var chain []RecordID
	seen := map[RecordID]bool{}
	cur := latest
	for cur != "" {
		if seen[cur] {
			return nil, &CorruptError{Slot: slot, Record: cur, Reason: "历史链出现环"}
		}
		seen[cur] = true
		env, err := a.loadAndVerifyLocked(cur)
		if err != nil {
			// 缺失、无法解析或校验不过：无法继续确认更老记录的归属，
			// 旧历史在此断裂。已确认的部分仍然可用。
			break
		}
		chain = append(chain, cur)
		if env.SlotFirst {
			break
		}
		cur = env.Parent
	}
	if len(chain) == 0 {
		return nil, &CorruptError{Slot: slot, Record: latest, Reason: "槽最新记录无法确认归属"}
	}
	return chain, nil
}

