func (a *Archive) assertInSlotHistoryLocked(slot string, id RecordID) error {
	_, history, _, err := a.slotHistoryLocked(slot)
	if err != nil {
		return err
	}
	for _, cid := range history {
		if cid == id {
			return nil
		}
	}
	return &NotFoundError{Slot: slot, Record: id}
}

