// slotHistoryLocked 返回该槽按保存生效次序排列的记录标识（最新在前、
// 槽首记录在末尾）。complete 为 true 表示这是一份完整历史：要么来自
// 指针内嵌索引，要么回退重建时已沿校验通过的父链走到槽首记录。
//
// 旧版本指针没有历史索引时，在内存中沿“校验通过”的记录父链回退重建，
// 绝不在读取路径上改写目录。重建在缺失、无法解析或校验不过的记录处
// 停止，complete 为 false——无法确认归属的更老记录不再使用。槽首标记
// 只取自校验通过的信封，因此受损记录里被篡改的父标识或槽首标记既不能
// 把遍历引向别的槽，也不能遮住本槽更早的可用记录。
func (a *Archive) slotHistoryLocked(slot string) (latest RecordID, history []RecordID, complete bool, err error) {
	p, err := a.readSlotPointerLocked(slot)
	if err != nil {
		return "", nil, false, err
	}
	if len(p.History) > 0 {
		// 以 Latest 为链头做一次去重规范化，容忍索引中的重复项。
		history = append([]RecordID{p.Latest}, p.History...)
		history = dedupeRecordIDs(history)
		return p.Latest, history, true, nil
	}
	history, complete, err = a.rebuildHistoryLocked(slot, p.Latest)
	if err != nil {
		return "", nil, false, err
	}
	return p.Latest, history, complete, nil
}

// rebuildHistoryLocked 从 latest 起沿校验通过的父链在内存中重建历史。
// 只返回仍能确认属于本槽的记录；complete 报告是否已走到槽首记录。
func (a *Archive) rebuildHistoryLocked(slot string, latest RecordID) ([]RecordID, bool, error) {
	var chain []RecordID
	seen := map[RecordID]bool{}
	cur := latest
	for cur != "" {
		if seen[cur] {
			return nil, false, &CorruptError{Slot: slot, Record: cur, Reason: "历史链出现环"}
		}
		seen[cur] = true
		env, err := a.loadAndVerifyLocked(cur)
		if err != nil {
			// 缺失、无法解析或校验不过：无法继续确认更老记录的归属，
			// 旧历史在此断裂；已确认的部分仍可使用。
			return chain, false, nil
		}
		chain = append(chain, cur)
		if env.SlotFirst {
			return chain, true, nil
		}
		cur = env.Parent
	}
	// 父链在到达槽首记录前自然耗尽：已确认部分可用，但历史不完整。
	return chain, false, nil
}

