		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(dir, slotsName, "s.json"), []byte("{not json"), 0o600); err != nil {
		t.Fatal(err)
	}
	if _, err := a.RecoverLatest("s", []string{"v1"}); !errors.As(err, new(*CorruptError)) {
		t.Fatalf("槽指针不可读应 Corrupt，得到 %T: %v", err, err)
	}
}

